SET NAMES utf8mb4;
SET SESSION FOREIGN_KEY_CHECKS=0;
SET SESSION UNIQUE_CHECKS=0;

SET SESSION check_constraint_checks=0;
-- ─── Reference data (LOAD DATA INFILE) ──────────────────
LOAD DATA LOCAL INFILE 'C:/hospitalDB/data_loader/csv/diagnosi.csv'
INTO TABLE diagnosi
